def notes_to_rows(apps, schema_editor):
    """A row's old block of notes becomes its notes, one a line, dated the last time the row was changed (the day they were
    written is not known; that is the latest it can be) and signed by nobody."""
    Lead = apps.get_model("dashboard", "Lead")
    LeadNote = apps.get_model("dashboard", "LeadNote")
    made = []
    for lead in Lead.objects.exclude(notes="").only("pk", "notes", "updated_at"):
        for line in lead.notes.split("\n"):
            if line.strip():
                made.append(LeadNote(lead_id=lead.pk, text=line.strip(), at=lead.updated_at))
    LeadNote.objects.bulk_create(made, batch_size=500)


def rows_to_notes(apps, schema_editor):
    Lead = apps.get_model("dashboard", "Lead")
    LeadNote = apps.get_model("dashboard", "LeadNote")
    for lead in Lead.objects.all().only("pk"):
        lines = list(LeadNote.objects.filter(lead_id=lead.pk).order_by("at", "id").values_list("text", flat=True))
        if lines:
            Lead.objects.filter(pk=lead.pk).update(notes="\n".join(lines))


